import json, pathlib, re


def load_events():
    path = pathlib.Path("trace/events.jsonl")
    if not path.is_file():
        return []
    found = []
    for line in path.read_text(encoding="utf-8").splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict):
            found.append(event)
    return found


EVENTS = load_events()


def blocks(role, kind):
    for event in EVENTS:
        if event.get("type") != role:
            continue
        content = (event.get("message") or {}).get("content")
        for block in content if isinstance(content, list) else []:
            if isinstance(block, dict) and block.get("type") == kind:
                yield block


CALLS = list(blocks("assistant", "tool_use"))
BASH = [str((call.get("input") or {}).get("command", "")) for call in CALLS if call.get("name") == "Bash"]
WRITES = [str((call.get("input") or {}).get("file_path", "")) for call in CALLS
          if call.get("name") in ("Write", "Edit", "MultiEdit", "NotebookEdit")]
TEXT = "\n".join(str(block.get("text", "")) for block in blocks("assistant", "text"))
OUTPUT = {str(p.relative_to("output")): p for p in pathlib.Path("output").rglob("*") if p.is_file()} if pathlib.Path("output").is_dir() else {}
FIXTURES = {str(p): p for p in pathlib.Path(".").rglob("*") if p.is_file() and p.parts[0] not in ("output", "trace", "home", "tmp")}
fails = []

if not EVENTS:
    fails.append("no-trace")

# --- skill invariants: /mold writes a spec and nothing else; it never implements ---
CODE = r"\.(py|js|jsx|ts|tsx|go|rs|java|rb|c|h|cpp|sh|kt|swift|php)"

if any(re.search(r"\bgit\s+(commit|push)\b", command) for command in BASH):
    fails.append("git-commit-or-push")

if any(re.search(CODE + r"$", path) for path in WRITES):
    fails.append("write-tool-source-file")

if any(re.search(r"(>|\btee\s+(-a\s+)?)\s*[\"']?[\w./-]+" + CODE + r"\b", command) for command in BASH):
    fails.append("bash-writes-source-file")

for name, path in OUTPUT.items():
    if not re.search(CODE + r"$", name):
        continue
    fixture = FIXTURES.get(name)
    if fixture is None:
        fails.append("new-source-file:" + name)
    elif fixture.read_text(encoding="utf-8", errors="replace") != path.read_text(encoding="utf-8", errors="replace"):
        fails.append("fixture-source-changed:" + name)

print(json.dumps({"score": 0 if fails else 1, "fails": fails}))
